compliant:
import { Effect } from "effect"

interface SearchDocument {
  readonly id: string
  readonly title: string
  readonly body: string
}

interface SearchIndex {
  readonly upload: (
    documents: ReadonlyArray<SearchDocument>
  ) => Promise<{ readonly accepted: number }>
  readonly refresh: () => Promise<void>
}

export const publishDocuments = (
  index: SearchIndex,
  documents: ReadonlyArray<SearchDocument>
) =>
  Effect.gen(function*() {
    if (documents.length === 0) {
      return { accepted: 0 }
    }

    const result = yield* Effect.promise(() => index.upload(documents))
    yield* Effect.promise(() => index.refresh())
    return result
  })
